/** Single-row variant of the shared group styles; buttons keep their natural width inside the scroll area. */
const ACTION_SELECTOR_ROW_SX = {
    ...ACTION_SELECTOR_GROUP_SX,
    flexWrap: 'nowrap',
    '& .MuiToggleButtonGroup-grouped': {
        ...ACTION_SELECTOR_GROUP_SX['& .MuiToggleButtonGroup-grouped'],
        flexShrink: 0,
        whiteSpace: 'nowrap',
    },
} as const
const SELECTED_BUTTON_SELECTOR = '[aria-pressed="true"]'

interface ActionSelectorProps {
    actions: ActionDefinition[]
    context: ActionContext
    onSelect: (actionId: string) => void
    selectedAction: ActionDefinition
    selectedHasForEach?: boolean
}

/** Horizontally scrollable, mutually exclusive action selector used by the card Run popup. */
export function ActionSelector(props: ActionSelectorProps) {
    const { actions, context, onSelect, selectedAction, selectedHasForEach = false } = props
    const activeRuns = useActiveActionRunsForContext(context)
    const groupRef = useRef<HTMLDivElement>(null)
    const activeActionStatuses: Record<string, ActionRunStatus> = {}
    for (const { rootActionId, status } of activeRuns) {
        if (status === 'waitingForInput' || !activeActionStatuses[rootActionId]) activeActionStatuses[rootActionId] = status
    }
    const handleChange = (_event: MouseEvent<HTMLElement>, actionId: string | null) => {
        if (actionId) onSelect(actionId)
    }

    useEffect(() => {
        const selectedButton = groupRef.current?.querySelector(SELECTED_BUTTON_SELECTOR)
        selectedButton?.scrollIntoView({ block: 'nearest', inline: 'nearest' })
    }, [selectedAction.id])

    return (
        <HorizontalScrollArea>
            <ToggleButtonGroup
                aria-label="Actions"
                exclusive
                onChange={handleChange}
                ref={groupRef}
                size="small"
                sx={ACTION_SELECTOR_ROW_SX}
                value={selectedAction.id}
            >
                {actions.map((action) => (
                    <ActionSelectorButton
                        action={action}
                        context={context}
                        key={action.id}
                        liveStatus={activeActionStatuses[action.id]}
                        hasForEach={action.id === selectedAction.id && selectedHasForEach}
                    />
                ))}
            </ToggleButtonGroup>
        </HorizontalScrollArea>
    )
}

import type { CardActivityFile, ActionActivityRecord } from '../../../../../../shared/card_activity.mjs'
import { BUILTIN_CUSTOM_PROMPT, CUSTOM_PROMPT_ACTION_ID, type ActionDefinition } from '../../../../data/action_types'
import type { ActionRunHistoryEntry } from '../../../../data/electron_action_bridge'
import type { PermissionMode, ThinkingLevel } from '../../../../data/agent_profiles'

function historicalDefinition(actionId: string, label: string, type: ActionDefinition['type']): ActionDefinition {
    return {
        ...BUILTIN_CUSTOM_PROMPT,
        builtin: false,
        command: type === 'command' ? '' : null,
        description: label,
        id: actionId,
        label,
        prompt: type === 'agent' ? '' : null,
        type,
    }
}

/** Adds action identities found in stored runs or conversations to current applicable actions. */
export function historicalCardActions(
    applicableActions: ActionDefinition[],
    loadedActions: ActionDefinition[],
    activities: CardActivityFile[],
) {
    const historical = new Map<string, { label: string, type: ActionDefinition['type'] }>()
    for (const activity of activities) {
        for (const record of activity.records) {
            if (record.type === 'system' || record.rootActionId === CUSTOM_PROMPT_ACTION_ID) continue
            historical.set(record.rootActionId, {
                label: record.rootActionLabel || record.rootActionId,
                type: record.details.type,
            })
        }
        for (const conversation of activity.conversations) {
            if (!conversation.actionId || conversation.actionId === CUSTOM_PROMPT_ACTION_ID) continue
            if (!historical.has(conversation.actionId)) {
                historical.set(conversation.actionId, { label: conversation.actionId, type: 'agent' })
            }
        }
    }

    const actions = applicableActions.filter(({ id }) => id !== CUSTOM_PROMPT_ACTION_ID)
    for (const [actionId, { label, type }] of historical) {
        if (actions.some(({ id }) => id === actionId)) continue
        actions.push(loadedActions.find(({ id }) => id === actionId) ?? historicalDefinition(actionId, label, type))
    }

    const customPrompt = applicableActions.find(({ id }) => id === CUSTOM_PROMPT_ACTION_ID) ?? BUILTIN_CUSTOM_PROMPT
    return [...actions, customPrompt]
}

function historyEntry(record: ActionActivityRecord, repositoryRoot: string): ActionRunHistoryEntry {
    const commits = record.commits.map((commit) => ({
        ...commit,
        actionId: commit.actionId ?? record.rootActionId,
        actionName: commit.actionName ?? record.rootActionLabel,
        repositoryRoot,
    }))
    const base = {
        commits,
        completedAt: record.completedAt,
        startedAt: record.startedAt,
        status: record.status,
    }
    if (record.details.type === 'agent') {
        if (!record.rootConversationId) throw new Error(`Agent run missing conversation ID: ${record.runId}`)
        return {
            ...base,
            ...record.details,
            permissionMode: record.details.permissionMode as PermissionMode | undefined,
            rootConversationId: record.rootConversationId,
            thinkingLevel: record.details.thinkingLevel as ThinkingLevel | undefined,
        }
    }

    return { ...base, ...record.details }
}

/** Reads one action's persisted runs from activity already checked against card identity. */
export function historicalActionHistory(activities: CardActivityFile[], actionId: string, repositoryRoot: string) {
    return activities.flatMap(({ records }) => records
        .filter((record): record is ActionActivityRecord => record.type !== 'system' && record.rootActionId === actionId)
        .map((record) => historyEntry(record, repositoryRoot)))
}

import { useCallback, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import { dataService } from '../../../../services/data/data_service'

function historicalActivityKey(cardInternalId: string) {
    const { project, snapshot } = dataService.getState()
    const card = snapshot?.backgroundCards.find(({ header }) => header.internalId === cardInternalId)
    if (!card || !project) return null

    const references = card.header.agentLogReferences.join('\u0000')

    return `${project.id}\u0000${project.branch}\u0000${card.header.internalId}\u0000${references}`
}

function subscribeProjectChanges(listener: () => void) {
    dataService.addEventListener('changed', listener)

    return () => dataService.removeEventListener('changed', listener)
}

function subscribeNothing() {
    return () => undefined
}

/**
 * Activity key of a historical (background) card, derived from its project and activity references.
 * Background cards publish no per-field events; the primitive key keeps unrelated project changes
 * from rendering. Non-historical contexts do not subscribe at all.
 */
export function useHistoricalActivityKey(context: ActionContext) {
    const cardInternalId = context.kind === 'file' ? context.cardInternalId ?? null : null
    const subscribe = cardInternalId ? subscribeProjectChanges : subscribeNothing
    const getSnapshot = useCallback(() => cardInternalId ? historicalActivityKey(cardInternalId) : null, [cardInternalId])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

import type { CardActivityFile } from '../../../../shared/card_activity.mjs'
import { dataService } from '../data/data_service'
import { dialogService } from '../dialog_service'

/** Owns activity loaded for an open historical card popup. */
export class HistoricalCardActivityService extends EventTarget {
    private readonly snapshots = new Map<string, CardActivityFile[] | null>()

    getSnapshot(key: string) {
        return this.snapshots.get(key) ?? null
    }

    subscribe(key: string, listener: () => void) {
        this.addEventListener(key, listener)
        return () => this.removeEventListener(key, listener)
    }

    async load(key: string, cardInternalId: string, signal: AbortSignal) {
        this.snapshots.set(key, null)
        this.dispatchEvent(new Event(key))
        try {
            const activities = await dataService.loadReferencedCardActivities(cardInternalId)
            if (signal.aborted) return
            this.snapshots.set(key, activities)
            this.dispatchEvent(new Event(key))
        } catch (error) {
            if (!signal.aborted) dialogService.error(error, { fallbackMessage: 'Could not load card activity' })
        }
    }
}

